49		return index >= 0 ? args[index + 1] : undefined;
50	};
51	try {
52		if (command === 'fixture:ingest') {
53			const fixture = valueAfter('--fixture');
54			const ingest = isLegacyCandidateId(fixture)
55				? (options: { allowNetwork: boolean; consentId?: string }) =>
56						ingestLegacyCandidate({ ...options, fixture })
57				: fixture === 'angular-phonecat'
58					? ingestAngularPhonecat
59					: fixture === 'react-realworld-cra1-vite8'
60						? ingestReactRealworld
61						: fixture === 'react-boilerplate-v4-node24'
62							? ingestReactBoilerplateNode24
63							: ingestFixture;
