65				![
66					'react-boilerplate-v4',
67					'react-boilerplate-v4-node24',
68					'react-realworld-cra1-vite8',
69					'angular-phonecat',
70					'react-papercups-v1-0-0',
71				].includes(fixture ?? '')
72			)
