75				allowNetwork: args.includes('--allow-network'),
76				consentId: valueAfter('--consent-id'),
77			});
78			console.log(
79				JSON.stringify({
80					result: 'ingested',
81					fixture: result.manifest.id,
82					consentId: result.consent.consentId,
83				}),
84			);
85		} else if (command === 'fixture:verify' && isLegacyCandidateId(valueAfter('--fixture'))) {
86			if (!args.includes('--offline'))
87				throw new Error('Legacy corpus evidence verification requires --offline');
88			const verification = await verifyLegacyCandidateEvidence(
89				legacyCandidateConfig(valueAfter('--fixture')),
90			);
91			console.log(
92				JSON.stringify({
93					result: 'pass',
94					fixture: verification.fixture,
95					checks: verification.checks.length,
96					digest: verification.digest,
97				}),
98			);
99		} else if (command === 'fixture:verify') {
100			const fixture = valueAfter('--fixture');
101			if (
102				![
103					'react-boilerplate-v4',
104					'react-boilerplate-v4-node24',
105					'react-boilerplate-v4-vite8',
106					'react-boilerplate-v4-data-flow',
107					'react-boilerplate-v4-composed',
108					'angular-phonecat',
109					'angular-phonecat-composed',
110					'angular-phonecat-vite8',
111					'angular-phonecat-route-resolve',
112				].includes(fixture ?? '') ||
113				!args.includes('--offline')
114			)
115				throw new Error('Fixture verification requires a supported fixture and --offline');
116			const receiptPath = valueAfter('--receipt');
117			if (!receiptPath) throw new Error('--receipt is required');
118			const receipt =
119				fixture === 'angular-phonecat'
120					? await verifyAngularPhonecat({ receiptPath })
121					: fixture === 'angular-phonecat-composed'
122						? await verifyAngularPhonecatComposed({ receiptPath })
123						: fixture === 'angular-phonecat-vite8'
124							? await verifyAngularPhonecatVite8({ receiptPath })
125							: fixture === 'angular-phonecat-route-resolve'
126								? await verifyAngularPhonecatRouteResolve({ receiptPath })
127								: fixture === 'react-boilerplate-v4-node24'
128									? await verifyReactBoilerplateNode24({ receiptPath })
129									: fixture === 'react-boilerplate-v4-vite8'
130										? await verifyReactBoilerplateVite8({ receiptPath })
131										: fixture === 'react-boilerplate-v4-data-flow'
132											? await verifyReactBoilerplateDataFlow({ receiptPath })
133											: fixture === 'react-boilerplate-v4-composed'
134												? await verifyReactBoilerplateComposed({ receiptPath })
135												: await verifyReactFixture({ receiptPath });
136			console.log(JSON.stringify({ result: 'pass', digest: receipt.integrity.canonicalDigest }));
137		} else if (command === 'framework:classify') {
138			const descriptorPath = valueAfter('--descriptor');
139			if (!descriptorPath) throw new Error('framework:classify requires --descriptor');
140			console.log(
141				JSON.stringify(
142					await runFrameworkClassification({
143						descriptorPath,
144						offline: args.includes('--offline'),
145					}),
146				),
147			);
148		} else if (command === 'nextjs:provenance-classify') {
149			const fixture = valueAfter('--fixture');
150			const outputPath = valueAfter('--output');
151			if (!fixture || !outputPath || !args.includes('--offline'))
152				throw new Error(
153					'nextjs:provenance-classify requires --offline, --fixture, and --output',
154				);
155			const receipt = await runNextjsProvenanceClassification({
156				fixtureId: fixture,
157				outputPath,
158				offline: true,
159			});
160			console.log(
161				JSON.stringify({
162					result: 'pass',
163					fixture: receipt.closure.fixtureId,
164					digest: receipt.integrity.canonicalDigest,
165					networkAttempts: receipt.locality.networkAttempts,
166					candidateExecution: receipt.locality.candidateExecution,
167				}),
168			);
169		} else if (command === 'next13:provenance-classify') {
170			const fixture = valueAfter('--fixture');
171			const outputPath = valueAfter('--output');
172			if (!fixture || !outputPath || !args.includes('--offline'))
173				throw new Error(
174					'next13:provenance-classify requires --offline, --fixture, and --output',
175				);
176			const receipt = await runNext13ProvenanceClassification({
177				fixtureId: fixture,
178				outputPath,
179				offline: true,
180			});
181			console.log(
182				JSON.stringify({
183					result: 'pass',
184					fixture: receipt.closure.fixtureId,
185					digest: receipt.integrity.canonicalDigest,
186					networkAttempts: receipt.locality.networkAttempts,
187					candidateExecution: receipt.locality.candidateExecution,
188				}),
189			);
190		} else if (command === 'dependency:ingest' || command === 'dependency:verify') {
191			const fixture = valueAfter('--fixture');
192			if (fixture !== 'angular-fuxa')
193				throw new Error('Dependency closure requires --fixture angular-fuxa');
194			const dependencyArgs = [...args];
195			if (command === 'dependency:verify' && !dependencyArgs.includes('--verify-only'))
196				dependencyArgs.push('--verify-only');
197			await runAngularFuxaDependencyIngest(dependencyArgs);
198		} else if (command === 'angular-fuxa:standalone') {
199			await runAngularFuxaStandalone(args);
200		} else if (command === 'angular-fuxa:standalone-cohort') {
201			await runAngularFuxaStandaloneCohort(args);
202		} else if (command === 'angular-fuxa:template-compiler') {
203			await runAngularFuxaTemplateCompiler(args);
204		} else if (command === 'vite8:shared-adapter-cohort') {
205			await runVite8SharedAdapterCohort(args);
206		} else if (command === 'receipt:verify') {
207			const flags = args.filter((arg) => arg.startsWith('--'));
208			const paths = args.filter((arg) => !arg.startsWith('--'));
209			if (flags.some((flag) => flag !== '--pre-integration' && flag !== '--offline'))
210				throw new Error('receipt:verify received an unknown flag');
211			if (flags.filter((flag) => flag === '--pre-integration').length > 1)
212				throw new Error('receipt:verify received duplicate --pre-integration flags');
213			if (paths.length > 1)
214				throw new Error(
215					'receipt:verify requires exactly one receipt path when a path is supplied',
216				);
217			const preIntegration = flags.includes('--pre-integration');
218			if (preIntegration && paths.length !== 1)
219				throw new Error('receipt:verify --pre-integration requires exactly one receipt path');
220			const file = paths[0] ?? 'evidence/runs/react-boilerplate-v4-composed/t060-run.json';
221			if (
222				preIntegration &&
223				(process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
224					process.env.NPM_CONFIG_OFFLINE !== 'true')
225			)
226				throw new Error('receipt:verify --pre-integration requires dual offline controls');
227			console.log(
228				JSON.stringify(await verifyReceipt(file, { requireAggregate: !preIntegration })),
229			);
230		} else if (command === 'corpus:verify') {
231			if (process.env.VERSIONLESS_NETWORK_MODE !== 'offline' && !args.includes('--offline'))
232				throw new Error('corpus:verify requires VERSIONLESS_NETWORK_MODE=offline');
233			const result = await analyzeCorpusConformance();
234			console.log(
235				JSON.stringify({
236					result: 'pass',
237					digest: result.integrity.canonicalDigest,
238					verticals: result.summary.verticals,
239					sourceApplications: result.summary.sourceApplications,
240				}),
241			);
242		} else if (command === 'script-surface:verify') {
243			const result = await verifyScriptSurface();
244			console.log(
245				JSON.stringify({
246					result: 'pass',
247					verticals: result.summary.verticals,
248					sourceApplications: result.summary.sourceApplications,
249					lanes: result.summary.lanes,
250					externalScriptsIntroduced: result.summary.externalScriptsIntroduced,
251				}),
252			);
253		} else if (command === 'runtime-script-observation:verify') {
254			const configPath = valueAfter('--config');
255			const outputDir = valueAfter('--output');
256			if (!configPath || !outputDir || !args.includes('--offline'))
257				throw new Error(
258					'runtime-script-observation:verify requires --offline, --config, and --output',
259				);
260			const result = await verifyRuntimeScriptObservation({
261				configPath,
262				outputDir,
263				offline: true,
264			});
265			console.log(JSON.stringify({ result: 'pass', ...result.summary }));
266		} else if (command === 'direct-dom:inventory') {
267			const root = valueAfter('--root');
268			const id = valueAfter('--id');
269			const output = valueAfter('--output');
270			if (!root || !id || !output || !args.includes('--offline'))
271				throw new Error('direct-dom:inventory requires --offline, --root, --id, and --output');
272			const inventory = runDirectDomInventory({ root, id, output, offline: true });
273			console.log(
274				JSON.stringify({
275					result: 'pass',
276					id: inventory.id,
277					files: inventory.semanticEngine.files,
278					sites: inventory.counts.total,
279					digest: inventory.integrity.canonicalDigest,
280					networkAttempts: inventory.locality.networkAttempts,
281				}),
282			);
283		} else if (command === 'witness:real-app') {
284			if (args.includes('--verify-provenance-only')) {
285				console.log(JSON.stringify(await verifyLinkedWitnessProvenance()));
286			} else {
287				const publish = valueAfter('--publish');
288				const verify = valueAfter('--verify');
289				if (publish && args.includes('--run-twice')) {
290					const receipt = await runWitnessRealApps(publish);
291					console.log(
292						JSON.stringify({
293							result: receipt.result,
294							digest: receipt.integrity.canonicalDigest,
295						}),
296					);
297				} else if (verify) {
298					const receipt = await verifyWitnessRealApps(verify);
299					console.log(
300						JSON.stringify({
301							result: receipt.result,
302							digest: receipt.integrity.canonicalDigest,
303						}),
304					);
305				} else {
306					throw new Error(
307						'witness:real-app requires --verify-provenance-only, --run-twice --publish, or --verify',
308					);
309				}
310			}
311		} else if (command === 'witness:angular-realworld') {
312			const publish = valueAfter('--publish');
313			const verify = valueAfter('--verify');
314			if (publish && args.includes('--run-twice')) {
315				const receipt = await runWitnessAngularRealworld(publish);
316				console.log(
317					JSON.stringify({
318						result: receipt.result,
319						digest: receipt.integrity.canonicalDigest,
320					}),
321				);
322			} else if (verify) {
323				const receipt = await verifyWitnessAngularRealworld(verify);
324				console.log(
325					JSON.stringify({
326						result: receipt.result,
327						digest: receipt.integrity.canonicalDigest,
328					}),
329				);
330			} else {
331				throw new Error('witness:angular-realworld requires --run-twice --publish or --verify');
332			}
333		} else if (command === 'trust:ingest') {
334			const result = await ingestTrustInputs({
335				allowNetwork: args.includes('--allow-network'),
336				consentId: valueAfter('--consent-id'),
337			});
338			console.log(
339				JSON.stringify({
340					result: 'ingested',
341					purpose: result.purpose,
342					consentId: result.consent.consentId,
343					packages: result.packages.length,
344				}),
345			);
346		} else if (command === 'trust:generate') {
347			const policyPath = valueAfter('--policy');
348			const outputDir = valueAfter('--output');
349			if (!policyPath || !outputDir)
350				throw new Error('trust:generate requires --policy and --output');
351			console.log(
352				JSON.stringify(
353					await generateTrustPackage({
354						offline: args.includes('--offline'),
355						policyPath,
356						outputDir,
357					}),
358				),
359			);
360		} else if (command === 'report:enterprise') {
361			// The operator-facing flow an enterprise reviewer is handed: it verifies the
362			// trust package first, then re-derives the one machine artifact and the one
363			// human document from the same canonical receipts. `--verify-only` refuses
364			// to write, so a reviewer can check the published pair without touching it.
365			const outputDir = valueAfter('--output') ?? 'evidence/trust/current';
366			if (!args.includes('--offline'))
367				throw new Error('report:enterprise requires --offline');
368			const verifyOnly = args.includes('--verify-only');
369			const result = await runEnterpriseReport({
370				outputDir,
371				verifyOnly,
372				environment: { ...process.env, VERSIONLESS_NETWORK_MODE: 'offline' },
373			});
374			console.log(JSON.stringify(result));
375		} else if (command === 'trust:verify') {
376			const outputDir = args.find((arg) => !arg.startsWith('--'));
377			console.log(
378				JSON.stringify(
379					await verifyTrustPackage({
380						outputDir: outputDir ?? 'evidence/trust/current',
381						compareDir: valueAfter('--compare'),
382						environment: args.includes('--offline')
383							? { ...process.env, VERSIONLESS_NETWORK_MODE: 'offline' }
384							: process.env,
385					}),
386				),
387			);
388		} else throw new Error(`Unknown command: ${command}`);
389	} catch (error) {
390		console.error(error instanceof Error ? error.stack : String(error));
391		process.exitCode = 1;
392	}
