357	/**
358	 * Two builds of one lane and what they jointly prove. A green lane is
359	 * `deterministic` when both outputs carry the same digest. A red lane is
360	 * `stable` when both attempts failed the same way — the property that makes a
361	 * red result evidence rather than noise.
362	 */
363	export function summarizeLane(first: LaneBuild, second: LaneBuild): LaneRun {
364		const built = first.result === 'built' && second.result === 'built';
365		return {
366			first,
367			second,
368			deterministic:
369				built && first.inventory !== null && first.inventory.digest === second.inventory?.digest,
370			stable:
371				first.result === second.result &&
372				first.exitCode === second.exitCode &&
373				canonicalize(parseBuildDemands(first.log)) === canonicalize(parseBuildDemands(second.log)),
374		};
375	}
376	
377	/** Build the era-pinned baseline lane twice in its own runtime cell. */
378	export async function runBaselineLane(root = baselineRoot): Promise<LaneRun> {
379		await generateApplicationMocks(root);
380		return summarizeLane(
381			await buildBaselineLane('build-run1', root),
382			await buildBaselineLane('build-run2', root),
383		);
384	}
385	
386	export type TargetLaneRun = LaneRun &
387		Readonly<{
388			entryDocumentSha256: string;
389			modulesTransformed: number | null;
390			demands: readonly BuildDemand[];
391			externalized: readonly ExternalizedModule[];
392		}>;
393	
394	/**
395	 * Regenerate the entry document and build the migrated lane twice through the
396	 * frozen adapter composition, recording what the bundler demanded either way.
397	 */
398	export async function runTargetLane(
399		environment: Readonly<Record<string, string>>,
400		root = targetRoot,
401	): Promise<TargetLaneRun> {
402		await generateApplicationMocks(root);
403		const document = await writeCypressRwaEntryDocument(environment, root);
404		const first = await buildTargetLane('build-vite-run1', root);
405		const second = await buildTargetLane('build-vite-run2', root);
406		return {
407			...summarizeLane(first, second),
408			entryDocumentSha256: sha256(document),
409			modulesTransformed: parseModulesTransformed(first.log),
410			demands: parseBuildDemands(first.log),
411			externalized: parseExternalizedModules(first.log, root),
412		};
413	}
414	
415	/** Write an observation document into the holdout's run evidence directory. */
416	export async function writeRunObservation(name: string, value: unknown): Promise<string> {
417		const directory = path.join(repositoryRoot, 'evidence/runs/react-cypress-rwa');
418		await mkdir(directory, { recursive: true });
419		const file = path.join(directory, name);
420		await writeFile(file, `${JSON.stringify(value, null, '\t')}\n`);
421		return file;
422	}
423	
424	export const cypressRwaWorkArea = Object.freeze({
425		root: workRoot,
426		baseline: baselineRoot,
427		target: targetRoot,
428		viteConfig,
429	});
