		try {
			await writeUnclaimedReactTree(application);
			await writeFile(path.join(lane, 'kept.txt'), 'kept\n');
			const plan = {
				lineage: 'react',
				engine: 'test',
				cell: null,
				inputsSupplied: [],
				applicationFilesScanned: 0,
				files: [],
				removedFiles: [],
				unhandled: [],
				declaredDifferences: [],
				notEstablished: [],
			} as const;
