import { readFile, mkdir, writeFile } from 'node:fs/promises';
import * as path from 'pathe';

const root = '/Users/jacksm5pro/dev/open-source/versionless';
const { canonicalize } = await import(`${root}/packages/core/src/receipts/canonicalize.ts`);
