	`${root}/packages/cli/src/operator/plan.ts`
);
const fixture = await import(`${root}/packages/cli/src/fixture/angular-pigallery2-migration-run.ts`);
const react = await import(`${root}/packages/cli/src/fixture/react-cypress-rwa-migration-run.ts`);

const sha256 = (value: string): string => createHash('sha256').update(value).digest('hex');

const readings = {
	missingMemberDiagnostics: await fixture.readMissingMemberDiagnostics(fixture.PREVIOUS_BUILD_LOG),
	deepImportReadings: await fixture.readDeepImportReadings(fixture.APPLIED_TREE),
	eraClosureTypePackages: await fixture.readEraClosureTypePackages(fixture.ERA_CLOSURE_TREE),
};
const operator = await composeAngularPlan({
	appRoot: fixture.SOURCE_TREE,
	sourceDirectories: fixture.APPLICATION_SOURCE_DIRECTORIES,
	templateDirectories: ['frontend'],
	styleSheetDirectories: ['frontend'],
	readings,
